//! Target-version LVGL image resources generated by the page owner thread.

use alloc::vec::Vec;
use core::sync::atomic::{AtomicU32, Ordering};

use lyra_player_core::ui::{QR_IMAGE_PATH_A, QR_IMAGE_PATH_B, qr_modules, qr_resource_generation};

static RENDERED_QR: AtomicU32 = AtomicU32::new(0);
const QR_PIXELS: usize = 180;

pub fn ensure_qr(url: &str) -> Result<(), i32> {
    if url.is_empty() {
        return Ok(());
    }
    let generation = qr_resource_generation(url);
    if RENDERED_QR.load(Ordering::Acquire) == generation {
        return Ok(());
    }
    let modules = qr_modules(url).ok_or(-1)?;
    let path = if generation & 1 == 0 {
        QR_IMAGE_PATH_A
    } else {
        QR_IMAGE_PATH_B
    };
    let bytes = encode(&modules)?;
    super::storage::write_atomic_bytes(path, &bytes)?;
    RENDERED_QR.store(generation, Ordering::Release);
    Ok(())
}

fn encode(modules: &lyra_player_core::ui::QrModules) -> Result<Vec<u8>, i32> {
    let source_size = modules.size();
    if source_size == 0 || source_size > QR_PIXELS {
        return Err(-1);
    }
    let scale = QR_PIXELS / source_size;
    if scale == 0 {
        return Err(-1);
    }
    let image_size = source_size * scale;
    let mut output = Vec::with_capacity(header_size() + image_size * image_size * 4);
    append_header(&mut output, image_size)?;
    for y in 0..image_size {
        for x in 0..image_size {
            let pixel = if modules.dark(x / scale, y / scale) {
                [0u8, 0, 0, 0xFF]
            } else {
                [0xFFu8; 4]
            };
            output.extend_from_slice(&pixel);
        }
    }
    Ok(output)
}

#[cfg(feature = "target-xiaomi-band-9-pro-3-1-175")]
const fn header_size() -> usize {
    4
}

#[cfg(not(feature = "target-xiaomi-band-9-pro-3-1-175"))]
const fn header_size() -> usize {
    12
}

#[cfg(feature = "target-xiaomi-band-9-pro-3-1-175")]
fn append_header(output: &mut Vec<u8>, size: usize) -> Result<(), i32> {
    let size = u32::try_from(size).map_err(|_| -1)?;
    if size > 0x7FF {
        return Err(-1);
    }
    // LVGL v8 binary header: TRUE_COLOR_ALPHA (5), width and height packed into
    // the recovered 32-bit lv_img_header_t bitfield.
    let header = 5u32 | (size << 10) | (size << 21);
    output.extend_from_slice(&header.to_le_bytes());
    Ok(())
}

#[cfg(not(feature = "target-xiaomi-band-9-pro-3-1-175"))]
fn append_header(output: &mut Vec<u8>, size: usize) -> Result<(), i32> {
    let size = u16::try_from(size).map_err(|_| -1)?;
    let stride = u16::try_from(usize::from(size) * 4).map_err(|_| -1)?;
    // LVGL v9 binary header used by the existing Manager icon pipeline:
    // magic, ARGB8888 color format, flags, dimensions, stride, reserved.
    output.extend_from_slice(&[0x19, 0x10, 0, 0]);
    output.extend_from_slice(&size.to_le_bytes());
    output.extend_from_slice(&size.to_le_bytes());
    output.extend_from_slice(&stride.to_le_bytes());
    output.extend_from_slice(&[0, 0]);
    Ok(())
}
